"""Restore a tree produced by compress.py back into its original layout.

Usage:
    python /app/decompress.py <resharded_dir>

The restore is performed in place: the shard files are removed and the
original files and directories are written directly into <resharded_dir>.
"""

from __future__ import annotations

import argparse
import json
import os
import shutil
import stat
import struct
import sys
from pathlib import Path
from typing import List, Tuple

FORMAT_MAGIC = b"RSHRD001"
SHARD_MAGIC = b"RSHD"
SHARD_HEADER = struct.Struct(">4sII")
READ_CHUNK = 1 << 20


class StreamReader:
    """Sequential reader over the logical stream stored across shards."""

    def __init__(self, shards: List[Tuple[int, int, Path]]) -> None:
        self.shards = shards
        self.index = -1
        self.file = None
        self.remaining = 0
        self._open_next()

    def _open_next(self) -> None:
        if self.file is not None:
            self.file.close()
        self.index += 1
        if self.index >= len(self.shards):
            raise SystemExit("unexpected end of shard data")
        expected_index, expected_length, path = self.shards[self.index]
        self.file = open(path, "rb")
        header = self.file.read(SHARD_HEADER.size)
        if len(header) != SHARD_HEADER.size:
            raise SystemExit(f"truncated shard header: {path}")
        magic, index, length = SHARD_HEADER.unpack(header)
        if magic != SHARD_MAGIC or index != expected_index:
            raise SystemExit(f"corrupt shard header: {path}")
        if length != expected_length:
            raise SystemExit(f"shard length mismatch: {path}")
        self.remaining = length

    def read_exact(self, count: int) -> bytes:
        chunks: List[bytes] = []
        received = 0
        while received < count:
            if self.remaining == 0:
                self._open_next()
            take = min(count - received, self.remaining)
            data = self.file.read(take)
            if not data:
                raise SystemExit("truncated shard payload")
            chunks.append(data)
            received += len(data)
            self.remaining -= len(data)
        return b"".join(chunks)

    def ensure_eof(self) -> None:
        if self.remaining != 0 or self.index != len(self.shards) - 1:
            raise SystemExit("shard data does not match the manifest")

    def close(self) -> None:
        if self.file is not None:
            self.file.close()
            self.file = None


def find_shards(root: Path) -> List[Tuple[int, int, Path]]:
    shards: List[Tuple[int, int, Path]] = []
    seen = set()

    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            path = Path(dirpath) / name
            if path.is_symlink():
                raise SystemExit(f"unexpected symlink in sharded data: {path}")
            actual_size = path.stat().st_size
            with open(path, "rb") as handle:
                header = handle.read(SHARD_HEADER.size)
            if len(header) != SHARD_HEADER.size:
                raise SystemExit(f"not a resharded directory (bad file): {path}")
            magic, index, length = SHARD_HEADER.unpack(header)
            if magic != SHARD_MAGIC:
                raise SystemExit(f"not a resharded directory (bad file): {path}")
            if actual_size != SHARD_HEADER.size + length:
                raise SystemExit(f"shard size mismatch: {path}")
            if index in seen:
                raise SystemExit(f"duplicate shard index {index}: {path}")
            seen.add(index)
