            elif kind == "file":
                destination.parent.mkdir(parents=True, exist_ok=True)
                remaining = int(entry["size"])
                with open(destination, "wb") as handle:
                    while remaining > 0:
                        chunk = reader.read_exact(min(READ_CHUNK, remaining))
                        handle.write(chunk)
                        remaining -= len(chunk)
            elif kind == "symlink":
                destination.parent.mkdir(parents=True, exist_ok=True)
                if destination.exists() or destination.is_symlink():
                    destination.unlink()
                os.symlink(entry["target"], destination)
            else:
                raise SystemExit(f"unknown entry type in manifest: {kind!r}")

        reader.ensure_eof()
    finally:
        reader.close()

    # Shards are no longer needed.  The reserved top-level directory (or
    # directories) cannot contain restored data, so removing it is safe.
    for top in reserved_tops:
        target = root / top
        if target.is_dir() and not target.is_symlink():
            shutil.rmtree(target)
        else:
            target.unlink()

    # Apply modes and timestamps after all content exists, children first so
    # directory timestamps are not disturbed by later writes.
    entries.sort(key=lambda entry: entry["path"].count("/"), reverse=True)
    for entry in entries:
        destination = root.joinpath(*entry["path"].split("/"))
        apply_metadata(destination, entry)

    print(
        f"Restored {len(entries)} entries from {len(shards)} shard(s)",
        file=sys.stderr,
    )


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Restore a directory resharded by compress.py."
    )
    parser.add_argument("resharded_dir", help="directory to restore in place")
    args = parser.parse_args()

    restore(Path(args.resharded_dir))


